    "id": "90000000-0000-0000-0000-000000000210",
    "title": "Power Through Prayer",
    "description": "The full public-domain text of E. M. Bounds' Power Through Prayer, preserved in its original chapter structure.",
    "total_days": 21,
    "tags": [
      "prayer",
      "leadership",
