  v_day_id uuid;
begin
  for v_plan in
    select value
    from jsonb_array_elements($plans$
[
  {
    "id": "90000000-0000-0000-0000-000000000218",
    "title": "Prayer and Shared Scripture: Two Readings from an 1814 Pastoral Tract",
    "description": "Two Scripture-led readings adapted from Joseph Phillimore's 1814 Anglican pastoral tract. The readings retain its encouragement of daily prayer and access to Scripture while identifying the parish setting and omitting its confusion between Jesus' baptism and Pentecost, anti-dissenter polemic, denominational gatekeeping, and wartime nationalism.",
    "total_days": 2,
    "tags": [
      "obedience",
      "virtue",
      "wisdom"
    ],
    "cover_image": "https://images.unsplash.com/photo-1495446815901-a7297e633e8d?auto=format&fit=crop&w=1200&q=80",
    "source_url": "https://www.gutenberg.org/ebooks/62017",
    "days": [
      {
        "day_number": 1,
        "title": "Begin and End the Day with God",
        "content": "<p><strong>Read:</strong> Matthew 6:9-13; Philippians 4:6-7.</p><p><strong>Historical context:</strong> Joseph Phillimore addressed two English parishes in an 1814 pastoral tract. He urged households to pray morning and evening, although the complete tract also contains a factual confusion between Jesus' baptism and Pentecost and several claims this adaptation does not repeat.</p><p><strong>Source theme, in contemporary language:</strong> Regular prayer makes room to worship the Father, receive daily provision with gratitude, seek forgiveness, resist temptation, and bring both prosperity and adversity into God's presence through Jesus Christ.</p><p><strong>Reflect:</strong> Which edge of your day most needs an intentional pause with God? Choose a realistic time and place, and let the Lord's Prayer guide both your trust and your responsibilities.</p><p><strong>Prayer:</strong> Our Father, give us daily bread, forgive our sins, and lead us away from temptation. Guard our hearts and minds in Christ Jesus throughout this day. Amen.</p>",
        "references": [
          "Matthew 6:9-13",
          "Philippians 4:6-7"
        ]
      },
      {
        "day_number": 2,
        "title": "Share Scripture Without Favoritism",
        "content": "<p><strong>Read:</strong> James 2:1-5; 2 Timothy 3:14-17.</p><p><strong>Historical context:</strong> Phillimore asked wealthier parishioners to help place Christian books in homes that could not afford them. His proposal assumed Anglican worship, disparaged dissenting Christians, and appealed to British wartime victory; those sectarian and national claims are omitted here.</p><p><strong>Source theme, in contemporary language:</strong> Money and social position should not block a person from learning Scripture or participating in Christian community. Sharing Bibles, teaching, accessible formats, and patient companionship can help neighbors hear and practice God's word.</p><p><strong>Reflect:</strong> What barrier makes Scripture or Christian learning harder for someone near you—cost, language, literacy, disability, technology, or lack of welcome? Ask what would help and support access without controlling the person's conscience.</p><p><strong>Prayer:</strong> Lord Jesus, remove favoritism from your people. Help us share Scripture generously, teach with humility, welcome every neighbor, and honor the conscience of others. Amen.</p>",
        "references": [
          "James 2:1-5",
          "2 Timothy 3:14-17"
        ]
      }
    ]
  },
  {
    "id": "90000000-0000-0000-0000-000000000219",
    "title": "Praying for Freedom: Nine Readings from an Antislavery Tract",
    "description": "Nine devotional readings from James A. Thome's 1859 American antislavery tract and an appended sermon by E. N. Kirk. Each day presents a short, labeled editorial paraphrase of the historical argument, a Scripture focus, context, a new reflection, and a prayer. The source is an abolitionist appeal, not firsthand testimony from people who were enslaved. Its full text is linked.",
    "total_days": 9,
    "tags": [
      "prayer",
      "virtue",
      "wisdom"
    ],
    "cover_image": "https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=1200&q=80",
    "source_url": "https://www.gutenberg.org/ebooks/70704",
    "days": [
      {
        "day_number": 1,
        "title": "No Person Is Property",
        "content": "<p><strong>Scripture focus:</strong> Genesis 1:26-27</p><p><strong>Historical context:</strong> The 1859 tract opens with a separate antislavery statement by Albert Barnes, then begins Thome's own appeal. This reading follows Thome's opening account of slavery under American law.</p><p><strong>Source paraphrase — James A. Thome (1859):</strong> Thome says that slavery's central wrong is treating people as property. Its laws denied enslaved people rights and protection while serving the interests of those who claimed to own them.</p><p><strong>Reflection:</strong> Genesis names every human being as God's image-bearer. The law Thome describes contradicted that dignity; its victims were people with lives and voices of their own. Whose voice can you listen to today before speaking on their behalf?</p><p><strong>Prayer:</strong> Creator God, teach us to honor your image in every person. Expose ways we deny others dignity, and lead us to listen and act justly. Amen.</p>",
        "references": [
          "Genesis 1:26-27"
        ]
      },
      {
        "day_number": 2,
        "title": "The Spirit Helps Us Pray",
        "content": "<p><strong>Scripture focus:</strong> Romans 8:26-27</p><p><strong>Historical context:</strong> Thome rejects the claim that slavery was acceptable if individual owners were kind. He then turns to Christian prayer as part of the struggle to abolish the institution.</p><p><strong>Source paraphrase — James A. Thome (1859):</strong> The wrong lies in making a person someone else's possession, Thome argues. He urges believers to pray for its end, trusting the Holy Spirit to shape their petitions and Jesus Christ to intercede.</p><p><strong>Reflection:</strong> The Spirit helps us pray when we do not know what to say. Prayer is not a way to control God or avoid responsibility. Bring a specific injustice before him, and ask what love and truth require of you.</p><p><strong>Prayer:</strong> Holy Spirit, guide our prayers toward your justice. Lord Jesus, intercede for those harmed by oppression and make us faithful neighbors. Amen.</p>",
        "references": [
          "Romans 8:26-27"
        ]
      },
      {
        "day_number": 3,
        "title": "Face Injustice Directly",
        "content": "<p><strong>Scripture focus:</strong> Isaiah 58:6-7</p><p><strong>Historical context:</strong> Thome addresses churches that hoped slavery would fade without direct opposition. He writes before emancipation in the United States.</p><p><strong>Source paraphrase — James A. Thome (1859):</strong> Thome argues that the church must name slavery as sin, oppose it openly, and seek immediate emancipation. Quiet hope that it will disappear on its own is inadequate.</p><p><strong>Reflection:</strong> Isaiah joins worship to loosening unjust bonds and sharing what people need. When a wrong is known, what truthful and practical step can your community take? Listen first to those who bear its cost.</p><p><strong>Prayer:</strong> God of justice, keep our worship honest. Give your church courage to name wrong, hear those harmed, and pursue their freedom. Amen.</p>",
        "references": [
          "Isaiah 58:6-7"
        ]
      },
      {
        "day_number": 4,
        "title": "Remember the Oppressed Together",
        "content": "<p><strong>Scripture focus:</strong> Luke 18:1-8</p><p><strong>Historical context:</strong> In the tract's next section, Thome laments the absence of prayer for enslaved people in American church gatherings. He also reviews the public antislavery efforts of his day.</p><p><strong>Source paraphrase — James A. Thome (1859):</strong> Thome says believers should not leave enslaved people out of their shared prayers. He sees persistent prayer as necessary alongside public words and other attempts to end slavery.</p><p><strong>Reflection:</strong> Jesus' parable honors a widow who keeps asking for justice. A congregation can likewise remember people harmed by injustice without speaking over them. Whose stated needs could your community carry into prayer and concrete care?</p><p><strong>Prayer:</strong> Faithful God, hear those who cry out for justice. Keep our shared prayers attentive to their needs and move us toward faithful care. Amen.</p>",
        "references": [
          "Luke 18:1-8"
        ]
      },
      {
        "day_number": 5,
        "title": "Pray and Act for Freedom",
        "content": "<p><strong>Scripture focus:</strong> James 2:15-17</p><p><strong>Historical context:</strong> Thome calls Christians to pray urgently for abolition while acknowledging other means of opposing slavery. He resists an appeal to peace that would leave the institution intact.</p><p><strong>Source paraphrase — James A. Thome (1859):</strong> Thome urges sustained personal and shared prayer for enslaved people's freedom. He does not discard other efforts; he asks that prayer accompany an unambiguous demand to end slavery.</p><p><strong>Reflection:</strong> James asks what good it does to bless a neighbor while withholding needed help. Prayer can steady courageous action; action can give shape to prayer. What useful step is within your reach this week?</p><p><strong>Prayer:</strong> Lord, keep us from settling for words alone. Give us wisdom, perseverance, and practical love in the work of justice. Amen.</p>",
        "references": [
          "James 2:15-17"
        ]
      },
      {
        "day_number": 6,
        "title": "Remember People, Not an Abstraction",
        "content": "<p><strong>Scripture focus:</strong> Hebrews 13:3</p><p><strong>Historical context:</strong> After arguing against the institution, Thome turns attention to the people who suffered under it. His tract speaks about them from an abolitionist's position, not in their own voices.</p><p><strong>Source paraphrase — James A. Thome (1859):</strong> Thome insists that opposing slavery cannot remain an abstract position. Enslaved people belonged to the same human family, with rights, relationships, and hopes that slavery violated.</p><p><strong>Reflection:</strong> Hebrews asks us to remember people in prison as though bound with them. Remembering begins with refusing to reduce people to a cause or a statistic. Whose testimony could make your concern more attentive and specific?</p><p><strong>Prayer:</strong> God who sees each person, hear those whose freedom and relationships are threatened. Teach us to attend to their voices and defend their dignity. Amen.</p>",
        "references": [
          "Hebrews 13:3"
        ]
      },
      {
        "day_number": 7,
        "title": "Pray for Freedom without Favoritism",
        "content": "<p><strong>Scripture focus:</strong> James 2:1-9</p><p><strong>Historical context:</strong> Thome rejects prayers that assume bondage must continue. He also challenges racial prejudice that could make Christians less willing to pray for Black people enslaved in the United States.</p><p><strong>Source paraphrase — James A. Thome (1859):</strong> Thome asks believers to pray for emancipation, not only for comfort within slavery. He warns that prejudice must not diminish concern for enslaved neighbors.</p><p><strong>Reflection:</strong> James condemns favoritism among believers. Prayer for freedom should make room for people's own choices, families, work, and worship. Where might bias narrow the circle of people you notice or the freedom you want for them?</p><p><strong>Prayer:</strong> Impartial Lord, uncover prejudice in us. Teach us to seek freedom and full dignity for every neighbor. Amen.</p>",
        "references": [
          "James 2:1-9"
        ]
      },
      {
        "day_number": 8,
        "title": "Carry This Prayer into Community",
        "content": "<p><strong>Scripture focus:</strong> Galatians 6:2</p><p><strong>Historical context:</strong> Thome closes his tract by appealing to readers, parents, new believers, and ministers. The inherited slice then begins a separately attributed sermon; this reading draws only on Thome's closing appeal.</p><p><strong>Source paraphrase — James A. Thome (1859):</strong> Thome asks Christians to bring the wrongs suffered by enslaved people into private and gathered prayer. He calls households and churches to share this burden instead of overlooking it.</p><p><strong>Reflection:</strong> Bearing a burden together takes more than one moment of concern. Make room for sustained prayer, listening, and accountable help in your community. What practice could you begin or strengthen?</p><p><strong>Prayer:</strong> Lord Jesus, teach our households and churches to carry one another's burdens. Keep us attentive, humble, and steadfast. Amen.</p>",
        "references": [
          "Galatians 6:2"
        ]
      },
      {
        "day_number": 9,
        "title": "Repentance and Repair",
        "content": "<p><strong>Scripture focus:</strong> James 5:1-6</p><p><strong>Historical context:</strong> The source's final prose is an appended sermon by E. N. Kirk, not by Thome. Kirk addresses the harm done by slaveholders and calls Christians to pray for them as well as for those enslaved.</p><p><strong>Source paraphrase — E. N. Kirk (appended sermon):</strong> Kirk lists losses imposed on enslaved people: control over their work, wages, family life, and worship. He urges prayer that those who maintain slavery will turn from it.</p><p><strong>Reflection:</strong> James says withheld wages cry out to God. Concern for wrongdoers cannot take priority over the freedom and material needs of those harmed. Repentance must surrender unjust power and make repair where possible.</p><p><strong>Prayer:</strong> God of truth and mercy, hear those deprived of freedom and the fruit of their work. Turn oppressors from harm; bring justice, restitution, and healing. Amen.</p>",
        "references": [
          "James 5:1-6"
        ]
      }
    ]
  },
  {
    "id": "90000000-0000-0000-0000-000000000220",
    "title": "I'm Greatly Concerned About Your Soul.",
    "description": "A modern-English adaptation of the public-domain text of a searching evangelical tract centered on the soul's condition before God.",
    "total_days": 1,
