          "Galatians 6:8",
          "Acts 13:2",
          "Acts 13:4",
          "Acts 13:9",
          "Acts 13:52",
          "Acts 15:8",
          "Acts 15:28",
          "Acts 16:6-7",
          "John 20:22"
        ]
