    "days": [
      {
        "day_number": 1,
        "title": "Morning Prayer 1",
        "content": "<p>Good morning, God. Thank you for watching over me last night. Help me follow Jesus today, and be near to me in all that happens. Amen.</p>",
        "references": []
      },
      {
        "day_number": 2,
        "title": "Morning Prayer 2",
        "content": "<p>Father, thank you for waking me to a bright new day. Forgive me when I do wrong, and guide me by your love as I learn and play. Stay close to me through Jesus. Amen.</p>",
        "references": []
      },
      {
        "day_number": 3,
        "title": "Morning Prayer 3",
        "content": "<p>Lord, thank you for the rest of last night. Help me begin this day with joy and follow Jesus in what I do and say. Amen.</p>",
        "references": []
