          "1 Thessalonians 5:15",
          "Romans 12:10",
          "Romans 12:21",
          "Hebrews 13:5",
          "Ecclesiastes 9:10",
          "1 Corinthians 16:14",
          "James 1:2",
          "1 Timothy 5:22",
          "1 Thessalonians 5:18",
          "Ephesians 6:18"
